const raw = $input.item.json.output;

let parsed;
try {
  const cleaned = raw.replace(/```json\n?|```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    reasoning_steps: ["Parse failed before any reasoning could be read."],
    sender: "unknown",
    topic: null,
    proposed_date: null,
    proposed_time: null,
    duration_minutes: null,
    urgency: "medium",
    decision: "need_more_info",
    missing_info: ["Could not parse AI response: " + e.message],
    draft_response: null,
    event_start: null,
    event_end: null
  };
}

// the completeness gate reads these two - never let them be undefined
parsed.reasoning_steps = parsed.reasoning_steps || [];
parsed.missing_info = parsed.missing_info || [];

// stamped here so the no-reply check knows what 'new mail' means
parsed.askedAt = new Date().toISOString();

return { json: parsed };

